import java.io.*;
import java.util.*;

public class utkarsh {

    BufferedReader br;
    PrintWriter out;

    long mod = (long) (1e9 + 7), inf = (long) (3e18);

    long fact[], inv[];

    long nCr(int n, int r) {
        return fact[n] * inv[n-r] % mod * inv[r] % mod;
    }

    void solve() {
        mod = 998244353L;
        int n = ni();
        long k = nl();
        if(k >= n)  out.println(0);
        else {
            fact = new long[n+1];
            inv = new long[n+1];
            fact[0] = inv[0] = 1;
            for(int i = 1; i <= n; i++) fact[i] = (fact[i-1] * i) % mod;
            inv[n] = mp(fact[n], mod - 2);
            for(int i = n-1; i >= 1; i--)   inv[i] = ((i+1) * inv[i+1]) % mod;

            if(k == 0)  out.println(fact[n]);
            else {
                int r = n - (int)k;
                long ans = 0;
                int p = 1;
                for(int i = 0; i < r; i++) {
                    ans = (ans + p * nCr(r, i) * mp(r - i, n) % mod) % mod;
                    if(ans < 0) ans += mod;
                    p *= -1;
                }
                out.println((2 * nCr(n, r) * ans) % mod);
            }
        }
    }

    int gcd(int a, int b) {
        if(b == 0)  return a;
        return gcd(b, a % b);
    }

    long mp(long b, long e) {
        long r = 1;
        while(e > 0) {
            if( (e&1) == 1 )    r = (r * b) % mod;
            b = (b * b) % mod;
            e >>= 1;
        }
        return r;
    }

    // -------- I/O Template -------------

    char nc() {
        return ns().charAt(0);
    }

    String nLine() {
        try {
            return br.readLine();
        } catch(IOException e) {
            return "-1";
        }
    }

    double nd() {
        return Double.parseDouble(ns());
    }

    long nl() {
        return Long.parseLong(ns());
    }

    int ni() {
        return Integer.parseInt(ns());
    }

    StringTokenizer ip;

    String ns() {
        if(ip == null || !ip.hasMoreTokens()) {
            try {
                ip = new StringTokenizer(br.readLine());
            } catch(IOException e) {
                throw new InputMismatchException();
            }
        }
        return ip.nextToken();
    }

    void run() {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    public static void main(String[] args) {
        new utkarsh().run();
    }
}

